def profile():return account_shell('A little home for your details.',f'''<div class="profile-cards"><div class="soft-panel"><div class="section-head"><h2>Your profile</h2><span class="pill">Email verified</span></div><form class="profile-form">{input_('Name','Asha Sample')}<div class="field"><span>Sign-in email</span><p class="profile-email">asha@example.test</p></div><button class="button" type="submit">Save profile</button><p class="profile-status" role="status"></p></form></div><div class="soft-panel"><div class="section-head"><h2>Latest order</h2><span class="pill">Processing</span></div><h3>#KD-1042</h3><p>22 October 2026 · 2 sets</p><strong>₹3,160</strong>{a('14-order-detail','View your order '+icon('ArrowRight'),'underlink')}<hr><h3>Default address</h3><p>Asha Sample<br>12 Example Lane, Bengaluru<br>Karnataka 560001</p>{a('15-addresses','Manage addresses '+icon('ArrowRight'),'underlink')}</div></div><div class="inline-note">{icon('LockKeyhole')}These orders belong to your Kindred customer relationship. A shared buyer sign-in does not grant merchant access.</div>''')
def order_history():return account_shell('Your thoughtful choices.',f'''<div class="section-head"><h2>Orders at Kindred</h2><span>1 order</span></div><article class="history-card"><div class="section-head"><div><strong>#KD-1042</strong><p>22 October 2026</p></div><span class="pill">Processing</span></div><div class="history-products">{image('little-pause-open','Little Pause set')}{image('desk-companion','Desk Companion set')}<div><h3>Two ready-made sets</h3><p>Little Pause · Blush gift box<br>Desk Companion · Kraft gift box</p></div><strong>₹3,160</strong></div>{button('14-order-detail','View order')}</article><div class="pagination"><span>Page 1 of 1 · All orders shown</span></div><div class="soft-panel"><h3>Looking for an order?</h3><p>Use the same verified buyer account used at checkout. For help, contact the merchant with your order reference.</p></div>''','Orders','View only your orders at this store.')
def order_detail():return account_shell('Order #KD-1042',f'''<div class="section-head"><p>Placed 22 October 2026</p><span class="pill">Processing</span></div><div class="order-progress"><div class="done">{icon('CheckCircle2')}<strong>Order received</strong><span>22 Oct</span></div><div class="current">{icon('Package')}<strong>Processing</strong><span>Current status</span></div><div>{icon('Truck')}<strong>Shipped</strong><span>Not yet dispatched</span></div></div><div class="order-detail-grid"><div>{line()}{line(False)}{totals()}<div class="notice">Mock payment / fulfillment fixture · No real order was placed.</div></div><aside class="soft-panel"><h2>Order details</h2><h3>Deliver to</h3><p>Asha Sample<br>Flat 2, 12 Example Lane<br>Bengaluru, Karnataka 560001, India</p><h3>Payment</h3><p>Online · Mock paid state<br>₹3,160 · No real transaction</p><h3>Shipping</h3><p>Standard shipping · ₹80<br>Tracking not yet available.</p><h3>Need a hand?</h3><p>Quote #KD-1042 when contacting<br>hello@kindred.example.test</p>{a('13-orders','Back to orders','underlink')}</aside></div>''','Orders','Your owned order at Kindred · Selected packaging and quantities retained.')
def addresses():return account_shell('Where your gifts can go.',f'''<div class="address-layout"><section><div class="section-head"><h2>Saved addresses</h2><button class="underlink add-address" type="button">{icon('Plus')} Add address</button></div><article class="address-card"><div class="section-head"><h3>Home</h3><span class="pill">Default</span></div><p>Asha Sample<br>Flat 2, 12 Example Lane<br>Bengaluru, Karnataka 560001, India</p><div class="address-actions"><button class="underlink edit-address">Edit</button><button class="underlink delete-address">Delete</button></div></article><p class="small">Your buyer address book is private. Merchants receive only the delivery details needed for an order.</p></section><section class="soft-panel"><div class="section-head"><h2 id="address-title">Edit address</h2><span>Unsaved changes</span></div><form class="address-form">{input_('Full name','Asha Sample')}{input_('Address','12 Example Lane')}{input_('Apartment (optional)','Flat 2')}<div class="form-grid">{input_('City','Bengaluru')}{input_('PIN code','5600',error=True)}</div><p class="field-message" id="postal-error">Enter a 6-digit Indian PIN code.</p><div class="form-grid"><label class="field"><span>State</span><select><option>Karnataka</option></select></label><label class="field"><span>Country</span><select><option>India</option></select></label></div><label class="checkbox"><input type="checkbox" checked> Set as default address</label><div class="actions"><button class="button" type="submit">Save address</button><button class="underlink cancel-address" type="button">Cancel</button></div><p class="address-status" role="status"></p></form></section></div>''','Addresses','Manage your private buyer address book. Review the delivery address at checkout.')
scenes=[('01-home-top','Homepage · first half','/','Announcement, gift finder, occasion entry and open-box image',home_top),('02-home-bottom','Homepage · second half','/','Curated gifts, packaging, gift help, services and footer',home_bottom),('03-collection','Gift collection & search','/products','Independent occasion/recipient/budget filters and curated cards',collection),('04-product-selection','Product · selection','/products/little-pause','Named packaging SKUs, availability and fixed contents',main_product),('05-product-contents','Product · contents','/products/little-pause#contents','Open/closed box pair and exact checklist',contents),('06-product-continuation','Product · continuation','/products/little-pause#gift-help','Care, policy, limitations and independently priced related set',continuation),('07-cart','Cart','/cart','Variant labels, quantities, totals and recovery',cart),('08-checkout-address','Checkout · address','shared checkout /address','Canonical address, shipping quote and full summary',checkout_address),('09-checkout-review','Checkout · review & pay','shared checkout /review','Full summary, eligibility and retained retry',checkout_review),('10-sign-in','Canonical buyer sign-in','identity-platform sign-in','LetBuyy credentials with explicit Kindred destination',lambda:auth()),('11-create-account','Canonical buyer create-account','identity-platform signup','Email/password creation, then explicit signed-in Continue to Kindred state',lambda:auth(True)),('12-profile','Profile overview','/account','Profile editing and owned account navigation',profile),('13-orders','Order history','/account/orders','One owned fictional order, pagination and support',order_history),('14-order-detail','Owned order detail','/account/orders/KD-1042','Exact variants, quantities, totals and status',order_detail),('15-addresses','Saved addresses','/account/addresses','Default, add/edit, invalid PIN and recovery states',addresses)]
meta=[]
for id,title,route,desc,fn in scenes:
 page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} · Kindred design study</title><link rel="stylesheet" href="fonts.css"><link rel="stylesheet" href="styles.css"></head><body data-scene="{id}">{fn()}<script src="interactions.js"></script></body></html>'''
 (S/f'{id}.html').write_text(page)
 meta.append({'id':id,'title':title,'description':desc,'routeIntent':route,'source':f'source/{id}.html','boundary':'One homepage / one PDP split for review; no duplicate production routes.' if id[:2] in ['01','02','04','05','06'] else 'Presentation fixture; canonical implementation owner retained.'})
(R/'scenes.json').write_text(json.dumps(meta,indent=2)+'\n')
(R/'prototype-index.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kindred source prototype</title><link rel="stylesheet" href="source/fonts.css"><style>body{font:18px/1.6 Lato,Arial;margin:32px;background:#fffaf4;color:#342c2c}h1{font-family:Playfair Display,Georgia}a{color:#662e42}li{margin:18px 0;max-width:70ch}</style><h1>Kindred · editable responsive source</h1><p>Visual prototype · fictional fixtures · no real transactions or credentials.</p><p><a href="index.html">PNG storybook</a></p><ol>'+''.join(f'<li><a href="{m["source"]}">{m["title"]}</a><br>{m["description"]}</li>'for m in meta)+'</ol></html>')
print('Built',len(meta),'connected scenes')
